import{_ as a,o as n,c as r,a3 as i}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Cache","description":"","frontmatter":{"title":"Cache"},"headers":[],"relativePath":"projects/uix/debugging/cache.md","filePath":"projects/uix/debugging/cache.md","lastUpdated":1792850658000}'),t={name:"projects/uix/debugging/cache.md"};function l(c,e,o,s,h,d){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="cache-probleme" tabindex="-1">Cache-Probleme <a class="header-anchor" href="#cache-probleme" aria-label="Permalink to &quot;Cache-Probleme&quot;">​</a></h1><p>Nach Updates kann der Browser oder die Companion App alte Ressourcen behalten. In diesem Fall:</p><ul><li>Home Assistant neu laden.</li><li>Browser hart neu laden.</li><li>Companion-App-Cache leeren.</li><li>Prüfen, ob UIX eine Reload-Meldung zeigt.</li></ul><h2 id="typische-anzeichen" tabindex="-1">Typische Anzeichen <a class="header-anchor" href="#typische-anzeichen" aria-label="Permalink to &quot;Typische Anzeichen&quot;">​</a></h2><ul><li>Alte Styles bleiben sichtbar.</li><li>Neue YAML-Regeln wirken erst nach mehreren Reloads.</li><li>Desktop-Browser und Companion App zeigen unterschiedliche Ergebnisse.</li><li>Nach einem UIX-Update erscheint kurz eine Reload-Meldung.</li></ul><h2 id="empfehlung" tabindex="-1">Empfehlung <a class="header-anchor" href="#empfehlung" aria-label="Permalink to &quot;Empfehlung&quot;">​</a></h2><p>Die UIX-Aktion <a href="./../extras/uix-actions#clear-cache-home-assistant-frontend-cache-leeren"><code>clear-cache</code></a>, Alias <code>clear_cache</code>, leert gezielt den HA-Frontend-Anwendungscache und lädt den Browser neu. <strong><code>localStorage</code> bleibt erhalten</strong>, etwa die Browser-Mod-Browser-ID. Das ist vom pauschalen Löschen aller Browser-/App-Daten zu unterscheiden; für ein Ressourcenproblem ist solches Löschen nicht erforderlich.</p><p>Erst Home Assistant neu laden, dann den Browser hart neu laden. In der Companion App kann zusätzlich das Leeren des Frontend-Caches nötig sein.</p>',8)])])}const m=a(t,[["render",l]]);export{u as __pageData,m as default};
